public class FeatureScalerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String rounded(double[] values) {
        if (values == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < values.length; i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(Math.round(values[i] * 10000.0) / 10000.0);
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        try {
            check("normalize({2, 4, 6, 10})", "[0.0, 0.25, 0.5, 1.0]",
                    rounded(FeatureScaler.normalize(new double[]{2, 4, 6, 10})));
            check("normalize({-4, 0, 4}) handles negatives", "[0.0, 0.5, 1.0]",
                    rounded(FeatureScaler.normalize(new double[]{-4, 0, 4})));
            check("a constant column becomes all zeros", "[0.0, 0.0, 0.0]",
                    rounded(FeatureScaler.normalize(new double[]{5, 5, 5})));
            check("a single value becomes 0.0", "[0.0]",
                    rounded(FeatureScaler.normalize(new double[]{7})));
            check("an empty column stays empty", "[]",
                    rounded(FeatureScaler.normalize(new double[]{})));

            double[] input = {2, 4, 6, 10};
            FeatureScaler.normalize(input);
            check("the input column is not modified", "[2.0, 4.0, 6.0, 10.0]",
                    java.util.Arrays.toString(input));

            double[][] table = {{1, 10}, {3, 20}, {5, 50}};
            check("normalizeAll(table, 0)", "[0.0, 0.5, 1.0]", rounded(FeatureScaler.normalizeAll(table, 0)));
            check("normalizeAll(table, 1)", "[0.0, 0.25, 1.0]", rounded(FeatureScaler.normalizeAll(table, 1)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

