/**
 * Min-max scaling of a numeric feature column into the range 0..1.
 */
public class FeatureScaler {

    public static double[] normalize(double[] column) {
        double[] scaled = new double[column.length];
        if (column.length == 0) {
            return scaled;
        }
        double min = column[0];
        double max = column[0];
        for (double value : column) {
            if (value < min) {
                min = value;
            }
            if (value > max) {
                max = value;
            }
        }
        double range = max - min;
        if (range == 0.0) {
            return scaled;
        }
        for (int i = 0; i < column.length; i++) {
            scaled[i] = (column[i] - min) / range;
        }
        return scaled;
    }

    public static double[] normalizeAll(double[][] table, int col) {
        double[] column = new double[table.length];
        for (int i = 0; i < table.length; i++) {
            column[i] = table[i][col];
        }
        return normalize(column);
    }
}
